import { useCalendarStore } from "../state/calendar";

export function NowLine() {
  const { firstHour, lastHour } = useCalendarStore((state) => ({
    firstHour: state.firstHour,
    lastHour: state.lastHour,
  }));
  return <div data-range={`${firstHour}-${lastHour}`} />;
}

import { useAppSelector } from '../../store';

export default function Unread() {
  const [count, muted] = useAppSelector(s => [s.inbox.unread, s.inbox.muted]);
  return muted ? null : <span>{count}</span>;
}

import * as React from "react";
import { useBookerStoreContext } from "./BookerStoreProvider";

export const SlotList = () => {
  const [view] = useBookerStoreContext((s) => [s.view] as const);
  return <ul className={view} />;
};

import { usePagerStore } from "./pagerStore";

export function usePager() {
  return usePagerStore((state) => {
    const next = state.page + 1;
    return { page: state.page, next, goTo: state.goTo };
  });
}

import { useSelector } from '#redux';

export function Theme() {
  const theme = useSelector(function (state) {
    return { mode: state.prefs.mode, accent: state.prefs.accent };
  });
  return <div className={theme.mode} />;
}

import { stores } from "./stores";

export function Header() {
  const { title, subtitle } = stores.usePanelStore((s) => ({ title: s.title, subtitle: s.subtitle }));
  return <h1 title={subtitle}>{title}</h1>;
}

import { useLocaleStore } from "./localeStore";

export function LocaleSwitch() {
  const { locale, setLocale } = useLocaleStore((s) => ({ locale: s.locale, setLocale: s.setLocale }));
  return <button onClick={() => setLocale("fr")}>{locale}</button>;
}

import { useAppSelector } from "../store";

const selectHeader = (state: RootState) => ({ title: state.page.title, user: state.session.user });

export function Header() {
  const { title, user } = useAppSelector(selectHeader);
  return <h1 title={user?.name}>{title}</h1>;
}

import { useNavStore } from './nav';

function selectCrumbs(state) {
  return [state.section, state.page];
}

export function Crumbs() {
  const [section, page] = useNavStore(selectCrumbs);
  return <nav>{section} / {page}</nav>;
}

import { useCallback } from "react";
import { useInboxStore } from "./inboxStore";

export function Thread({ id }: { id: string }) {
  const select = useCallback((s: InboxState) => ({ thread: s.threads[id], draft: s.drafts[id] }), [id]);
  const { thread, draft } = useInboxStore(select);
  return <article data-draft={draft}>{thread.subject}</article>;
}

import * as R from "react";
import { useInboxStore } from "./inboxStore";

export function Row({ id }: { id: string }) {
  const select = R.useCallback((s: InboxState) => [s.threads[id], s.unread[id]], [id]);
  const [thread, unread] = useInboxStore(select);
  return <li data-unread={unread}>{thread.subject}</li>;
}

import React from 'react';
import { useInboxStore } from './inboxStore';

const { useCallback } = React;

export function Pill({ id }) {
  const select = useCallback((s) => ({ count: s.unread[id], muted: s.muted[id] }), [id]);
  const { count, muted } = useInboxStore(select);
  return muted ? null : <span>{count}</span>;
}

