import { create } from "zustand";

const useCounterStore = create<{ n: number; inc: () => void }>()((set) => ({
  n: 0,
  inc: () => set((s) => ({ n: s.n + 1 })),
}));

export function Counter() {
  const { n, inc } = useCounterStore((s) => ({ n: s.n, inc: s.inc }));
  return <button onClick={inc}>{n}</button>;
}

import { create } from "zustand";

const useBearStore = create<{ bears: number; fish: number; eat: () => void }>()((set) => ({
  bears: 0,
  fish: 10,
  eat: () => set((s) => ({ fish: s.fish - 1 })),
}));

export function BearCount() {
